let errorLog = global.get('error_log') || [];

// Vis de siste 10 feilene, nyeste først
const recent = errorLog.slice(-10).reverse();

msg.payload = recent.map(e => ({
    time: e.timestamp.replace('T', ' ').substring(0, 19),
    type: e.type.toUpperCase(),
    source: e.source,
    status: e.statusCode || 'none',
    message: e.message.substring(0, 60)
}));

return msg;

const rayvn_config = global.get('rayvn_config');

msg.headers = {
    "Authorization": "Bearer " + rayvn_config.api_key
};

msg.url = "https://api.rayvn.global/tags";

return msg;

const tags = msg.payload;

const wasosLabel = tags.find(tag => tag.name === "WaSOS");
const paratBridgeLabel = tags.find(tag => tag.name === "Parat-Bridge");

if (!wasosLabel || !paratBridgeLabel) {
    node.warn("Kunne ikke finne WaSOS eller Parat-Bridge label i /tags");
    return null;
}

global.set("wasosLabel", { id: wasosLabel.id, name: wasosLabel.name });
global.set("paratBridgeLabel", { id: paratBridgeLabel.id, name: paratBridgeLabel.name });

node.log("Labels satt: " + JSON.stringify({ wasosLabel, paratBridgeLabel }));

return msg;
